import base64
import zlib
import pygame

MAGES = {'pyro': (61, 71, 12, '', ''), 'wiz': (52, 67, 6, '', ''), 'skel': (76, 80, 6, '', '')}
MCACHE = {}


def mage_size(kind):
  return MAGES[kind][0], MAGES[kind][1]


def mage_frames(kind):
  return MAGES[kind][2]


def mage_frame(kind, fr):
  """Pixel-art caster facing left: 'pyro', 'wiz' or 'skel'."""
  w, h, n, pal, data = MAGES[kind]
  key = (kind, fr % n)
  s = MCACHE.get(key)
  if s is None:
    if (kind, "raw") not in MCACHE:
      MCACHE[(kind, "pal")] = [None] + [tuple(int(pal[i + k:i + k + 2], 16) for k in (0, 2, 4)) for i in range(0, len(pal), 6)]
      MCACHE[(kind, "raw")] = zlib.decompress(base64.b64decode(data))
    raw, p = MCACHE[(kind, "raw")], MCACHE[(kind, "pal")]
    s = pygame.Surface((w, h), pygame.SRCALPHA)
    base = key[1] * w * h
    for i in range(w * h):
      v = raw[base + i]
      if v:
        s.set_at((i % w, i // w), p[v] + (255,))
    MCACHE[key] = s
  return s
